#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>

/* Forward declaration of the fuzz target */
int fuzz_parse_http_request(const uint8_t *data, size_t length);

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t length) {
    return fuzz_parse_http_request(data, length);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <poc_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", argv[1]);
        return 1;
    }

    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);

    if (len > 32767) len = 32767;

    uint8_t *data = (uint8_t*)malloc(len);
    fread(data, 1, len, f);
    fclose(f);

    printf("Calling fuzz_parse_http_request with %ld bytes...\n", len);
    fflush(stdout);

    int result = LLVMFuzzerTestOneInput(data, len);

    printf("Result: %d\n", result);
    free(data);
    return 0;
}
EOF
echo "Created standalone_test.c"

